mapper.update:
UPDATE tbl_member_quest
SET status = 'DONE',
    completed_at = NOW()
WHERE id = #{id}
  AND member_email = #{email}
  AND status = 'TODO'

mapper.select:
SELECT COUNT(*)
FROM tbl_member_quest
WHERE member_email = #{email}
  AND status = 'DONE'
  AND assigned_date BETWEEN #{from} AND #{to}

SELECT COUNT(*)
FROM tbl_member_quest
WHERE member_email = #{email}
  AND assigned_date BETWEEN #{from} AND #{to}

SELECT COALESCE(SUM(q.reward), 0)
FROM tbl_member_quest mq
JOIN tbl_quest q ON mq.quest_id = q.quest_id
WHERE mq.member_email = #{email}
  AND mq.status = 'DONE'
  AND mq.assigned_date BETWEEN #{from} AND #{to}

SELECT DISTINCT assigned_date
FROM tbl_member_quest
WHERE member_email = #{email}
  AND status = 'DONE'
  AND assigned_date >= #{from}
ORDER BY assigned_date DESC

SELECT COUNT(*)
FROM tbl_member_quest mq
JOIN tbl_quest q ON mq.quest_id = q.quest_id
WHERE mq.member_email = #{email}
  AND mq.assigned_date = #{date}
  AND q.type = #{type}

SELECT COUNT(*)
FROM tbl_member_quest mq
JOIN tbl_quest q ON mq.quest_id = q.quest_id
WHERE mq.member_email = #{email}
  AND mq.assigned_date = #{date}
  AND q.type = #{type}

SELECT COUNT(*)
FROM tbl_member_quest mq
JOIN tbl_quest q ON mq.quest_id = q.quest_id
WHERE mq.member_email = #{email}
  AND mq.assigned_date BETWEEN #{from} AND #{to}
  AND q.type = #{type}

mapper.update:
UPDATE tbl_member_quest
SET status = 'EXPIRED'
WHERE member_email = #{email}
  AND status = 'TODO'
  AND due_date < #{today}

mapper.select:
SELECT quest_id, title, description, type, difficulty, theme,
       reward, urgency, due_days, active
FROM tbl_quest
WHERE quest_id = #{questId}
  AND type = #{type}
  AND active = TRUE
